const p = $json.body || $json;

const company = String(p.company || '').trim() || 'there';
const niche = String(p.niche || 'local service').trim();
const country = String(p.country || '').trim();
const city = String(p.city || '').trim();
const website = String(p.website || '').trim();
const rawIssue = String(p.issue || '').trim();

// Internal CRM/enrichment notes must NEVER be copied into client-facing outreach.
const internalOnlyPatterns = [
  /needs? verification/i,
  /do not claim/i,
  /safe[_ ]?to[_ ]?outreach/i,
  /verification[_ ]?status/i,
  /contactable/i,
  /wikidata/i,
  /openstreetmap|\bosm\b/i,
  /generic search[- ]engine scraping/i,
  /prospect still/i,
  /internal/i,
];

const isClientSafeIssue = rawIssue && !internalOnlyPatterns.some((rx) => rx.test(rawIssue));
const safeIssue = isClientSafeIssue ? rawIssue.replace(/\.+$/, '') : '';

const location = city
  ? `${city}${country ? `, ${country}` : ''}`
  : country;

let websiteLine;
if (website) {
  if (safeIssue) {
    websiteLine = `I took a look at your website and noticed ${safeIssue.charAt(0).toLowerCase() + safeIssue.slice(1)}.`;
  } else {
    websiteLine = `I took a look at your website and saw an opportunity to make the online presentation clearer and make it even easier for potential customers to request a quote.`;
  }
} else {
  websiteLine = `I couldn't find a clear dedicated website for ${company}, so I thought a simple site focused on your services and quote requests could be useful.`;
}

const where = location ? ` in ${location}` : '';
const variants = [
  {
    subject: `Quick idea for ${company}`,
    opener: `I came across ${company} while looking at ${niche} businesses${where}.`,
  },
  {
    subject: `Website idea for ${company}`,
    opener: `I found ${company} while researching local ${niche} companies${where}.`,
  },
  {
    subject: `A small idea for ${company}`,
    opener: `I was checking ${niche} businesses${where} and came across ${company}.`,
  },
];

const v = variants[Math.floor(Math.random() * variants.length)];
const message = `Hi ${company} team,\n\n${v.opener}\n\n${websiteLine}\n\nI design clean websites for local service businesses and can also help with branding or flyers when useful.\n\nI can prepare a free homepage concept first so you can see the direction before deciding anything.\n\nWould you like me to send it?\n\nBest,\n7KeySolutions`;

return [{
  json: {
    ...p,
    subject: v.subject,
    message,
    approval_status: 'pending',
    created_at: new Date().toISOString(),
  },
}];
